INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 0, 'theory', 'Quiz: programming languages and Python');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 0, 'What is a programming language?', '["A set of keys on a keyboard", "A go-between that a human and a processor can agree on", "A drawing program", "A language only for websites"]', 1, 'A processor understands only numeric commands, while a person thinks in images. A programming language lets you describe a task clearly for a human and precisely for a machine.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 1, 'How does an interpreter differ from a compiler?', '["An interpreter reads and runs the program step by step, while a compiler translates it as a whole in advance", "They don''t differ at all", "An interpreter works only on a server", "A compiler can''t report errors"]', 0, 'Python is run by an interpreter: type a line and get the result at once. A compiler (as in C and Rust) builds the program first, and only then do you run it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 2, 'Why is Python a good first language?', '["It is the fastest language in the world", "It has no errors", "It reads almost like English, is popular and has a rich standard library", "It is only suitable for children"]', 2, 'A low barrier to entry, readability, a large community and batteries included give a quick start without giving up serious capabilities.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 3, 'Which pair of Python application areas is named correctly?', '["Only games and design", "Web development and machine learning", "Only writing drivers", "Only accounting"]', 1, 'Python powers the server side of websites (Django, FastAPI), trains neural networks (NumPy, PyTorch) and automates routine work. It also appears in operating system utilities.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 4, 'What is a function for in programming?', '["To color text", "To turn off the computer", "To store pictures", "To gather a set of actions under one name and call it many times"]', 3, 'A function removes repetition: describe it once and call it as often as needed. It has parameters as input and a result as output.');
